-- ============================================================================
-- superi.ge — 40: „ქურის ზედაპირი“ კატეგორიის მოწესრიგება (104 პროდუქტი)
-- 1) კატეგორია: სრული ტექსტი (გაზის / ინდუქციური / ელექტრო / კომბინირებული, ზომა, მასალა, მონტაჟი,
--    პოპულარული მოდელები, კითხვა-პასუხი, ბმულები ბრენდებზე, ღუმელებსა და გამწოვებზე) + მეტა აღწერა. სახელი არ იცვლება.
-- 2) 104 პროდუქტის სახელს ემატება ტიპი, ერთიანი ფორმით: „გაზის / ინდუქციური / ელექტრო / კომბინირებული ქურის ზედაპირი BRAND MODEL“.
--    სათაური (page title) მხოლოდ იქ იცვლება, სადაც ძველი სახელის ზუსტი ასლი იყო — ახალი სახელით, იგივე ფორმით.
-- 3) 104 უნიკალური მეტა აღწერა რეალური მახასიათებლებით (160 სიმბოლომდე).
-- 4) აღწერები: GORENJE GTW641EB-ს გამწოვის (WHI629EB) ტექსტი ეწერა → ჩაიწერა მისი სწორი აღწერა (იგივე, რაც GTW641EW-ს, შავი ფერით);
--    BOSCH PKN652FP2E-დან ამოღებულია ღუმელის შეცდომით ჩაწერილი სტრიქონები; KUMTEL/LUXELL — „კომბინირებული“ → „გაზის“;
--    შეცდომები და რუსული სიტყვები: თერმომდრადი, სტეკლოკერამიკა, კომფორი, ფორსუნკები, плавური / плавная.
-- 5) ბრენდი აკლდა: BOSCH PXX375FB1E და MIDEA MG9005TX → დაემატა.
-- 6) 8 უხეირო მისამართი გასწორდა (ძველი 301-ით გადადის ახალზე): hob-aeg-aeg-hkb64453nb-4gas-60cm-black-glass → aeg-hkb64453nb და სხვ.
-- 7) საიტის ძებნის სინონიმები: ჩასაშენებელი ქურა, ქურის ზედაპირები, ინდუქცია, ჰობი, варочная панель, კერამიკული ქურა …
-- ასლები: superi_bk_cat_40, superi_bk_prod_40, superi_bk_seo_40, superi_bk_feat_40. ხელახლა გაშვება უსაფრთხოა. დაბრუნება ბოლოშია.
-- ატვირთვის შემდეგ: Live search → Synonyms → „Rebuild synonym index“ → ქეშის გასუფთავება.
-- ============================================================================
SET NAMES utf8mb4;
SET @f := (SELECT src FROM cscart_seo_redirects WHERE TRIM(BOTH '/' FROM src) = 'category-15' LIMIT 1);
SET @pre := IF(@f IS NULL OR LEFT(@f,1) = '/', '/', '');
SET @post := IF(@f IS NULL OR RIGHT(@f,1) = '/', '/', '');

-- 0) ასლები (მხოლოდ პირველ გაშვებაზე)
CREATE TABLE IF NOT EXISTS superi_bk_cat_40 AS SELECT cd.category_id, cd.lang_code, cd.description, cd.meta_description FROM cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'quris-zedapiri' WHERE cd.lang_code = 'ka';
CREATE TABLE IF NOT EXISTS superi_bk_prod_40 AS SELECT pd.product_id, pd.lang_code, pd.product, pd.page_title, pd.meta_description, pd.full_description FROM cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 WHERE pd.lang_code = 'ka' AND s.name IN ('aeg-hkb64420nb', 'aeg-ikb32300cb-30', 'beko-bisw-65120-sb-b300', 'beko-hdce-32200-x-b100', 'beko-hdcg-32220-fx', 'beko-hdmc-32200-x', 'beko-hibg-64122-sx', 'beko-hibw-64125-sb-b100', 'beko-hibw-64125-sx-b100', 'beko-hic-64402-t', 'beko-higg-641c3-sx', 'beko-higm-64123-sx', 'beko-hii-64200-mt', 'beko-hilw-64225-sw-bpro-500', 'beko-himl-95225-sxe-bpro-500', 'beko-hinw-64229-s', 'bosch-accent-line-carbon-black-induction-hob-pxy875kv1e', 'bosch-accent-line-hobs-with-integrated-extractor-hood-pxx895d66e', 'bosch-pbp6c5k60q', 'bosch-pci6b1b90r', 'bosch-pcp6a5b90m', 'bosch-pcp6a5i90m', 'bosch-pcq7a5m90', 'bosch-pgp6b6k90r', 'bosch-pgp6b6o92r', 'bosch-pke611ba1r', 'bosch-pkf375fp2e', 'bosch-pkn652fp2e', 'bosch-pnh6b6o92r', 'bosch-pnk6b2p40r', 'bosch-pnk6b2p41r', 'bosch-pnk6b6p41r', 'bosch-pnp6b2o92r', 'bosch-pop7c2p31o', 'bosch-pph6a6b20', 'bosch-ppp6a2i40r', 'bosch-ppp6a6b10', 'bosch-ppq7a6b20', 'bosch-ppq7a6i45', 'bosch-prp6a6d70r', 'bosch-prp6a6h40r', 'bosch-prs9a6d70m', 'bosch-pry6a6b70q', 'bosch-pue611bb5e', 'bosch-pue612bb1e', 'bosch-pxx375fb1e', 'electrolux-ege6182nok', 'electrolux-egg3322nvx', 'electrolux-egs6436sx', 'electrolux-gpe363nk', 'electrolux-kgg64362k', 'electrolux-kgu643723z', 'elenberg-c6-40btf-black', 'franko-fih-1180', 'gorenje-ec642clb', 'gorenje-ec642cli', 'gorenje-ect321bcsc', 'gorenje-ect322bcsc', 'gorenje-ect641bx', 'gorenje-g642ab', 'gorenje-g642abx', 'gorenje-gc321b', 'gorenje-gce681bsc', 'gorenje-ge680mb', 'gorenje-ge681x', 'gorenje-ge690x', 'gorenje-gtw641eb', 'gorenje-gtw641ew', 'gorenje-gw642ab', 'gorenje-gw642abx', 'gorenje-gw642syw', 'gorenje-gw6d42clb', 'gorenje-gw6d42cli', 'gorenje-it-646-orab', 'graetz-5411-85b', 'haier-hhq-m64ctqx', 'haier-hhq-m64cx', 'hhx-y64tfvb', 'higg64125scr', 'hilm-64222-sv', 'hob-aeg-aeg-hkb64453nb-4gas-60cm-black-glass', 'icy2000sp', 'indesit-thpm-642-ws-bl-i', 'kumtel-ko-40tahdf-b', 'luxell-c6-40bf-ant-ko-40tahde-ant', 'midea-60sk005', 'midea-mc-6f6404r244', 'midea-mc-id3591-a2', 'midea-mc-if7454aj1-a', 'midea-mc-if7454aj1c-a', 'midea-mg30sb005dt1b', 'midea-mg3260gb', 'midea-mg631gab', 'midea-mg631sas', 'midea-mg684tgw', 'midea-mg696tgb', 'midea-mg696trgb-b', 'midea-mg9005th', 'midea-mg9060tgb', 'samsung-na64h3000ak-wt', 'samsung-na64h3010as-wt', 'samsung-na64h3030ak-wt', 'samsung-na64h3030bk-wt', 'samsung-na64h3040as-wt');
CREATE TABLE IF NOT EXISTS superi_bk_seo_40 AS SELECT * FROM cscart_seo_names WHERE type = 'p' AND lang_code = 'ka' AND company_id = 1 AND name IN ('hob-aeg-aeg-hkb64453nb-4gas-60cm-black-glass', 'icy2000sp', 'higg64125scr', 'hhx-y64tfvb', 'hilm-64222-sv', 'bosch-accent-line-carbon-black-induction-hob-pxy875kv1e', 'bosch-accent-line-hobs-with-integrated-extractor-hood-pxx895d66e', 'midea-mg9005th');
SET @pxx := (SELECT object_id FROM cscart_seo_names WHERE type = 'p' AND lang_code = 'ka' AND company_id = 1 AND name = 'bosch-pxx375fb1e' LIMIT 1);
SET @mg9 := (SELECT object_id FROM cscart_seo_names WHERE type = 'p' AND lang_code = 'ka' AND company_id = 1 AND name IN ('midea-mg9005th', 'midea-mg9005tx') LIMIT 1);
CREATE TABLE IF NOT EXISTS superi_bk_feat_40 AS SELECT * FROM cscart_product_features_values WHERE product_id IN (@pxx, @mg9);

-- 1) კატეგორია: ტექსტი და მეტა აღწერა
UPDATE cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'quris-zedapiri' SET cd.description = '<p><strong>ქურის ზედაპირი</strong> (ჩასაშენებელი ქურა) სამზარეულოს სამუშაო მაგიდაში ჩაშენდება და ინტერიერს ერთიან, თანამედროვე სახეს აძლევს, ღუმელის დამონტაჟება კი ცალკე, ნებისმიერ სიმაღლეზეა შესაძლებელი. Superi.ge-ზე 100-ზე მეტი მოდელია: გაზის, ინდუქციური, ელექტრო და კომბინირებული ზედაპირები 30-დან 90 სმ-მდე — <a href="https://superi.ge/bosch/">Bosch</a>, <a href="https://superi.ge/gorenje/">Gorenje</a>, <a href="https://superi.ge/beko/">Beko</a>, <a href="https://superi.ge/midea/">Midea</a>, <a href="https://superi.ge/samsung/">Samsung</a>, <a href="https://superi.ge/electrolux/">Electrolux</a>, <a href="https://superi.ge/aeg/">AEG</a>, <a href="https://superi.ge/haier/">Haier</a> და სხვა ბრენდები.</p><h2>როგორ შევარჩიოთ ქურის ზედაპირი</h2><ul><li><strong>გაზის ზედაპირი</strong> — ყველაზე გავრცელებული არჩევანია: ალი მყისიერად რეგულირდება და ნებისმიერი ჭურჭელი გამოდგება. ბევრ მოდელს თხევად გაზზე (ბალონზე) გადასაყვანი საქშენებიც მოყვება. აირჩიეთ გაზკონტროლით (ალის ჩაქრობისას გაზი ავტომატურად ითიშება), ელექტროანთებითა და თუჯის ცხაურით.</li><li><strong>ინდუქციური ზედაპირი</strong> — ყველაზე სწრაფი და უსაფრთხო: მხოლოდ ჭურჭელს აცხელებს, ზედაპირი ნაკლებად ცხელდება და ადვილად იწმინდება. სჭირდება მაგნიტურძირიანი ჭურჭელი და სიმძლავრეზე გათვლილი ელექტროგაყვანილობა.</li><li><strong>ელექტრო (მინა-კერამიკული) ზედაპირი</strong> — გლუვი ზედაპირი Hi-Light ზონებით: ნებისმიერი ბრტყელძირიანი ჭურჭელი ერგება და ინდუქციურზე ხელმისაწვდომია.</li><li><strong>კომბინირებული ზედაპირი</strong> — 3 გაზის და 1 ელექტრო კონფორი (ან 2+2): კარგი არჩევანია, თუ გაზი ან დენი ხანდახან ითიშება.</li><li><strong>ზომა:</strong> სტანდარტული სიგანე 60 სმ-ია (4 კონფორი). 30 სმ-იანი „დომინო“ პატარა სამზარეულოსა და დამატებითი ზედაპირისთვისაა, 75–90 სმ-იანი კი, 5 კონფორით, დიდი ოჯახისთვის.</li><li><strong>ზედაპირის მასალა:</strong> ნაწრთობი მინა ლამაზი და ადვილად საწმენდია, უჟანგავი ფოლადი — გამძლე და პრაქტიკული, ემალი — ხელმისაწვდომი.</li><li><strong>მონტაჟი:</strong> ყიდვამდე გაზომეთ სამუშაო მაგიდის ნიში — 60 სმ-იან ზედაპირს ჩვეულებრივ დაახლოებით 56 × 48–49 სმ ჭრილი სჭირდება. ზუსტი ზომა თითოეული მოდელის მახასიათებლებშია მითითებული.</li></ul><h2>პოპულარული ქურის ზედაპირები</h2><ul><li><strong>გაზის, 60 სმ:</strong> <a href="https://superi.ge/bosch-pnk6b6p41r/">Bosch PNK6B6P41R</a>, <a href="https://superi.ge/bosch-pcp6a5b90m/">Bosch PCP6A5B90M</a>, <a href="https://superi.ge/samsung-na64h3040as-wt/">Samsung NA64H3040AS/WT</a>, <a href="https://superi.ge/gorenje-gw642syw/">Gorenje GW642SYW</a>, <a href="https://superi.ge/beko-hibg-64122-sx/">Beko HIBG 64122 SX</a>.</li><li><strong>გაზის, 75–90 სმ (5 კონფორი):</strong> <a href="https://superi.ge/bosch-ppq7a6b20/">Bosch PPQ7A6B20</a>, <a href="https://superi.ge/bosch-prs9a6d70m/">Bosch PRS9A6D70M</a>, <a href="https://superi.ge/beko-himl-95225-sxe-bpro-500/">Beko HIML 95225 SXE</a>, <a href="https://superi.ge/midea-mg9060tgb/">Midea MG9060TGB</a>.</li><li><strong>ინდუქციური:</strong> <a href="https://superi.ge/bosch-pue611bb5e/">Bosch PUE611BB5E</a>, <a href="https://superi.ge/bosch-pue612bb1e/">Bosch PUE612BB1E</a>, <a href="https://superi.ge/midea-mc-if7454aj1c-a/">Midea MC-IF7454AJ1C-A</a>, <a href="https://superi.ge/haier-hhx-y64tfvb/">Haier HHX-Y64TFVB</a>, <a href="https://superi.ge/gorenje-it-646-orab/">Gorenje IT 646 ORAB</a>.</li><li><strong>ელექტრო:</strong> <a href="https://superi.ge/gorenje-ect641bx/">Gorenje ECT641BX</a>, <a href="https://superi.ge/bosch-pke611ba1r/">Bosch PKE611BA1R</a>, <a href="https://superi.ge/beko-hic-64402-t/">Beko HIC 64402 T</a>.</li><li><strong>კომბინირებული:</strong> <a href="https://superi.ge/gorenje-ge680mb/">Gorenje GE680MB</a>, <a href="https://superi.ge/bosch-pry6a6b70q/">Bosch PRY6A6B70Q</a>, <a href="https://superi.ge/electrolux-ege6182nok/">Electrolux EGE6182NOK</a>.</li><li><strong>30 სმ (დომინო):</strong> <a href="https://superi.ge/bosch-pxx375fb1e/">Bosch PXX375FB1E</a> (ინდუქციური), <a href="https://superi.ge/bosch-pkf375fp2e/">Bosch PKF375FP2E</a> (ელექტრო), <a href="https://superi.ge/electrolux-egg3322nvx/">Electrolux EGG3322NVX</a> და <a href="https://superi.ge/midea-mg3260gb/">Midea MG3260GB</a> (გაზის).</li></ul><p>ზედაპირთან ერთად შეარჩიეთ <a href="https://superi.ge/chasashenebeli-ghumelebi/">ჩასაშენებელი ღუმელი</a> და <a href="https://superi.ge/gamtsovi/">გამწოვი</a>. თუ ღუმელიანი ქურა გჭირდებათ, იხილეთ <a href="https://superi.ge/gazqurebi/">გაზქურები</a>.</p><h2>ხშირად დასმული კითხვები</h2><h3>რომელი ჯობია — გაზის თუ ინდუქციური ზედაპირი?</h3><p>გაზის ზედაპირი უფრო ხელმისაწვდომია, ნებისმიერ ჭურჭელს ერგება და გაზის ქსელზე ან ბალონზე მუშაობს. ინდუქციური უფრო სწრაფი, უსაფრთხო და ადვილად საწმენდია, მაგრამ მაგნიტურძირიან ჭურჭელს და ძლიერ ელექტროგაყვანილობას საჭიროებს.</p><h3>რა ჭურჭელი სჭირდება ინდუქციურ ქურას?</h3><p>ისეთი, რომლის ძირსაც მაგნიტი ეკვრის: ფოლადის, თუჯის ან „induction“ ნიშნით მონიშნული. ალუმინის, სპილენძისა და მინის ჭურჭელი მაგნიტური ძირის გარეშე არ გაცხელდება.</p><h3>შეიძლება გაზის ზედაპირის ბალონზე გამოყენება?</h3><p>დიახ, ბევრ მოდელს თხევადი გაზის (G30/G31) საქშენები კომპლექტში მოყვება. ზედაპირი თხევად გაზზე სპეციალისტმა უნდა გადაიყვანოს.</p><h3>რა ზომის ნიშა სჭირდება?</h3><p>60 სმ-იან ზედაპირს ჩვეულებრივ დაახლოებით 56 × 48–49 სმ ჭრილი სჭირდება, 30 სმ-იანს — დაახლოებით 27 × 49 სმ. ზუსტი ზომა თითოეული მოდელის მახასიათებლებშია.</p><h3>შემიძლია ნაწილ-ნაწილ ყიდვა?</h3><p>დიახ, Superi.ge-ზე ქურის ზედაპირის შეძენა შეგიძლიათ ნაწილ-ნაწილ გადახდით. თბილისში მიწოდება უფასოა 100₾-დან, ასევე ვაწვდით მთელ საქართველოში.</p>' WHERE cd.lang_code = 'ka';
UPDATE cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'quris-zedapiri' SET cd.meta_description = 'ქურის ზედაპირი: გაზის, ინდუქციური, ელექტრო და კომბინირებული, 30–90 სმ — Bosch, Gorenje, Beko, Midea და სხვა. ✓ ნაწილ-ნაწილ გადახდა ✓ მიწოდება' WHERE cd.lang_code = 'ka';

-- 2-3) პროდუქტები: სახელი ტიპით, სათაური (მხოლოდ სადაც სახელის ასლი იყო), მეტა აღწერა
DROP TEMPORARY TABLE IF EXISTS tmp_hob;
CREATE TEMPORARY TABLE tmp_hob AS SELECT s.name AS slug, pd.product AS new_name, pd.meta_description AS new_meta FROM cscart_seo_names s JOIN cscart_product_descriptions pd ON pd.product_id = s.object_id LIMIT 0;
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_hob t ON t.slug = s.name SET pd.page_title = CASE WHEN REPLACE(pd.page_title, ' ', '') = REPLACE(pd.product, ' ', '') THEN t.new_name WHEN REPLACE(pd.page_title, ' ', '') = CONCAT(REPLACE(pd.product, ' ', ''), '|Superi.ge') THEN CONCAT(t.new_name, ' | Superi.ge') ELSE pd.page_title END WHERE pd.lang_code = 'ka' AND IFNULL(pd.page_title, '') <> '';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_hob t ON t.slug = s.name SET pd.product = t.new_name WHERE pd.lang_code = 'ka';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 JOIN tmp_hob t ON t.slug = s.name SET pd.meta_description = t.new_meta WHERE pd.lang_code = 'ka';

-- 4) აღწერების გასწორება
-- GORENJE GTW641EB: გამწოვის ტექსტის ნაცვლად — ზედაპირის სწორი აღწერა (GTW641EW-ის, შავი ფერით). მხოლოდ თუ ჯერ კიდევ გამწოვის ტექსტი უწერია.
UPDATE cscart_product_descriptions eb JOIN cscart_seo_names s1 ON s1.object_id = eb.product_id AND s1.type = 'p' AND s1.lang_code = 'ka' AND s1.company_id = 1 AND s1.name = 'gorenje-gtw641eb' JOIN cscart_seo_names s2 ON s2.type = 'p' AND s2.lang_code = 'ka' AND s2.company_id = 1 AND s2.name = 'gorenje-gtw641ew' JOIN cscart_product_descriptions ew ON ew.product_id = s2.object_id AND ew.lang_code = 'ka' SET eb.full_description = REPLACE(REPLACE(ew.full_description, 'GTW641EW', 'GTW641EB'), '• ზედაპირის მასალა:', '• ფერი: შავი<br> • ზედაპირის მასალა:') WHERE eb.lang_code = 'ka' AND eb.full_description LIKE '%WHI629EB%' AND ew.full_description LIKE '%GTW641EW%';
-- BOSCH PKN652FP2E: ღუმელის სტრიქონები ზედაპირის აღწერაში
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'bosch-pkn652fp2e' SET pd.full_description = REPLACE(pd.full_description, '<br>• გაზქურის ენერგიის მოხმარება: 188,7 ვტ/კგ', '') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%<br>• გაზქურის ენერგიის მოხმარება: 188,7 ვტ/კგ%';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'bosch-pkn652fp2e' SET pd.full_description = REPLACE(pd.full_description, '<br>• კარის საკეტი', '') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%<br>• კარის საკეტი%';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'bosch-pkn652fp2e' SET pd.full_description = REPLACE(pd.full_description, '<br>• პროგრამის დისტანციურად გაშვების შესაძლებლობა', '') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%<br>• პროგრამის დისტანციურად გაშვების შესაძლებლობა%';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'bosch-pkn652fp2e' SET pd.full_description = REPLACE(pd.full_description, '<br>• მუშაობის რეჟიმის შემოწმება', '') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%<br>• მუშაობის რეჟიმის შემოწმება%';
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'bosch-pkn652fp2e' SET pd.full_description = REPLACE(pd.full_description, '<br>• მოწყობილობის დისტანციური დიაგნოსტიკა', '') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%<br>• მოწყობილობის დისტანციური დიაგნოსტიკა%';
-- KUMTEL / LUXELL: 4 გაზის კონფორი აქვთ — ტიპი „გაზის“
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name IN ('kumtel-ko-40tahdf-b', 'luxell-c6-40bf-ant-ko-40tahde-ant') SET pd.full_description = REPLACE(pd.full_description, 'ზედაპირის ტიპი: კომბინირებული', 'ზედაპირის ტიპი: გაზის') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%ზედაპირის ტიპი: კომბინირებული%';
-- KUMTEL / ELENBERG / MIDEA MG684TGW: ზომებში რუსული „х“ → „×“
UPDATE cscart_product_descriptions pd JOIN cscart_seo_names s ON s.object_id = pd.product_id AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name IN ('kumtel-ko-40tahdf-b', 'elenberg-c6-40btf-black', 'midea-mg684tgw') SET pd.full_description = REPLACE(pd.full_description, 'х', '×') WHERE pd.lang_code = 'ka' AND pd.full_description LIKE '%х%';
