-- 5) ბრენდი: BOSCH PXX375FB1E (BOSCH PUE611BB5E-ის მსგავსად), MIDEA MG9005TX (MIDEA MG9060TGB-ის მსგავსად)
SET @ref := (SELECT object_id FROM cscart_seo_names WHERE type = 'p' AND lang_code = 'ka' AND company_id = 1 AND name = 'bosch-pue611bb5e' LIMIT 1);
SET @bv := (SELECT fv.variant_id FROM cscart_product_features_values fv JOIN cscart_product_features f ON f.feature_id = fv.feature_id AND f.feature_type = 'E' WHERE fv.product_id = @ref AND fv.variant_id > 0 LIMIT 1);
SET @ref := (SELECT object_id FROM cscart_seo_names WHERE type = 'p' AND lang_code = 'ka' AND company_id = 1 AND name = 'midea-mg9060tgb' LIMIT 1);
SET @bv := (SELECT fv.variant_id FROM cscart_product_features_values fv JOIN cscart_product_features f ON f.feature_id = fv.feature_id AND f.feature_type = 'E' WHERE fv.product_id = @ref AND fv.variant_id > 0 LIMIT 1);

-- 6) მისამართები: ძველი 301-ით გადადის ახალზე (თუ ახალი მისამართი თავისუფალია)
DROP TEMPORARY TABLE IF EXISTS tmp_slug;
CREATE TEMPORARY TABLE tmp_slug AS SELECT object_id AS pid, name AS old_name, name AS new_name FROM cscart_seo_names LIMIT 0;
ALTER TABLE tmp_slug ADD COLUMN ok TINYINT NOT NULL DEFAULT 0;
UPDATE tmp_slug t JOIN cscart_seo_names s ON s.name = t.old_name AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET t.pid = s.object_id;
UPDATE tmp_slug t SET t.ok = 1 WHERE t.pid > 0 AND NOT EXISTS (SELECT 1 FROM cscart_seo_names s2 WHERE s2.name = t.new_name);
UPDATE tmp_slug t JOIN cscart_seo_names s ON s.name = t.new_name AND s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1 SET t.pid = s.object_id, t.ok = 2 WHERE t.ok = 0 AND t.pid = 0;
DELETE r FROM cscart_seo_redirects r JOIN tmp_slug t ON TRIM(BOTH '/' FROM r.src) = t.new_name AND t.ok = 1 WHERE r.company_id = 1;
UPDATE cscart_seo_names s JOIN tmp_slug t ON t.pid = s.object_id AND t.old_name = s.name AND t.ok = 1 SET s.name = t.new_name WHERE s.type = 'p' AND s.lang_code = 'ka' AND s.company_id = 1;

-- 7) ძებნის სინონიმები (იგივე JSON ფორმატი, რაც 35/38-ში)
-- ქურის ზედაპირი  ←  ქურის ზედაპირები, ჩასაშენებელი ქურა, ჩასაშენებელი ზედაპირი, ჩასაშენებელი ქურის ზედაპირი, ჰობი, hob, варочная панель
SET @sid := (SELECT synonym_id FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'ქურის ზედაპირი' ORDER BY synonym_id LIMIT 1);
-- გაზის ქურის ზედაპირი  ←  ჩასაშენებელი გაზქურა, გაზქურის ზედაპირი, გაზის ზედაპირი, გაზის ჩასაშენებელი ზედაპირი
SET @sid := (SELECT synonym_id FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'გაზის ქურის ზედაპირი' ORDER BY synonym_id LIMIT 1);
-- ინდუქციური ქურის ზედაპირი  ←  ინდუქციური ქურა, ინდუქციური ზედაპირი, ინდუქცია, индукционная плита, индукционная панель
SET @sid := (SELECT synonym_id FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'ინდუქციური ქურის ზედაპირი' ORDER BY synonym_id LIMIT 1);
-- ელექტრო ქურის ზედაპირი  ←  კერამიკული ქურა, მინაკერამიკული ქურა, ვიტროკერამიკული ქურა, ელექტრო ზედაპირი
SET @sid := (SELECT synonym_id FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'ელექტრო ქურის ზედაპირი' ORDER BY synonym_id LIMIT 1);

-- 8) შემოწმება
SELECT s.name AS slug, cd.category, CHAR_LENGTH(REGEXP_REPLACE(IFNULL(cd.description, ''), '<[^>]*>', '')) AS text_chars, CHAR_LENGTH(cd.meta_description) AS meta_chars FROM cscart_category_descriptions cd JOIN cscart_seo_names s ON s.object_id = cd.category_id AND s.type = 'c' AND s.lang_code = 'ka' AND s.company_id = 1 AND s.name = 'quris-zedapiri' WHERE cd.lang_code = 'ka';
SELECT COUNT(*) AS products, SUM(pd.meta_description LIKE '%✓ ნაწილ-ნაწილ გადახდა%') AS new_metas, SUM(pd.product LIKE '%ქურის ზედაპირი %' OR pd.product LIKE 'პორტატული ინდუქციური ქურა %') AS typed_names, MAX(CHAR_LENGTH(pd.meta_description)) AS max_meta_chars FROM cscart_product_descriptions pd JOIN superi_bk_prod_40 b ON b.product_id = pd.product_id AND b.lang_code = pd.lang_code;
SELECT COUNT(*) AS typos_left FROM cscart_product_descriptions pd JOIN superi_bk_prod_40 b ON b.product_id = pd.product_id AND b.lang_code = pd.lang_code WHERE pd.full_description LIKE '%თერმომდრადი%' OR pd.full_description LIKE '%სტეკლოკერამიკა%' OR pd.full_description LIKE '%კომფორი%' OR pd.full_description LIKE '%კომფორებ%' OR pd.full_description LIKE '%კომფორა%' OR pd.full_description LIKE '%ფორსუნკ%' OR pd.full_description LIKE '%плавური%' OR pd.full_description LIKE '%плавე%' OR pd.full_description LIKE '%плавная%' OR pd.full_description LIKE '%WHI629EB%' OR pd.full_description LIKE '%კარის საკეტი%';
SELECT t.old_name, t.new_name, CASE t.ok WHEN 1 THEN 'გადაკეთდა' WHEN 2 THEN 'უკვე გაკეთებულია' ELSE 'გამოტოვდა' END AS result FROM tmp_slug t;
SELECT (SELECT COUNT(*) FROM cscart_product_features_values WHERE product_id = @pxx AND variant_id > 0) AS pxx_feature_rows, (SELECT COUNT(*) FROM cscart_product_features_values WHERE product_id = @mg9 AND variant_id > 0) AS mg9005_feature_rows;
SELECT phrase, synonyms FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase IN ('ქურის ზედაპირი', 'გაზის ქურის ზედაპირი', 'ინდუქციური ქურის ზედაპირი', 'ელექტრო ქურის ზედაპირი');
DROP TEMPORARY TABLE IF EXISTS tmp_slug;
DROP TEMPORARY TABLE IF EXISTS tmp_hob;

