INSERT IGNORE INTO cscart_product_features_values (feature_id, product_id, variant_id, value, value_int, lang_code) SELECT fv.feature_id, @pxx, fv.variant_id, fv.value, fv.value_int, fv.lang_code FROM cscart_product_features_values fv WHERE fv.product_id = @ref AND fv.variant_id = @bv AND @pxx IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_product_features_values x WHERE x.product_id = @pxx AND x.feature_id = fv.feature_id AND x.lang_code = fv.lang_code);
INSERT IGNORE INTO cscart_product_features_values (feature_id, product_id, variant_id, value, value_int, lang_code) SELECT fv.feature_id, @mg9, fv.variant_id, fv.value, fv.value_int, fv.lang_code FROM cscart_product_features_values fv WHERE fv.product_id = @ref AND fv.variant_id = @bv AND @mg9 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_product_features_values x WHERE x.product_id = @mg9 AND x.feature_id = fv.feature_id AND x.lang_code = fv.lang_code);
