INSERT IGNORE INTO cscart_seo_redirects (src, type, object_id, lang_code, company_id) SELECT CONCAT(@pre, t.old_name, @post), 'p', t.pid, 'ka', 1 FROM tmp_slug t WHERE t.ok = 1;
INSERT INTO cscart_csc_live_search_synonyms (company_id, phrase, synonyms, `timestamp`, user_id, lang_code, status) SELECT 1, 'ქურის ზედაპირი', '["ქურის ზედაპირები","ჩასაშენებელი ქურა","ჩასაშენებელი ზედაპირი","ჩასაშენებელი ქურის ზედაპირი","ჰობი","hob","варочная панель"]', UNIX_TIMESTAMP(), 0, 'ka', 'A' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'ქურის ზედაპირი');
INSERT INTO cscart_csc_live_search_synonym_words (synonym_id, company_id, lang_code, word, is_variant) SELECT @sid, 1, 'ka', w.word, 0 FROM (SELECT 'ქურის ზედაპირები' AS word UNION ALL SELECT 'ჩასაშენებელი ქურა' UNION ALL SELECT 'ჩასაშენებელი ზედაპირი' UNION ALL SELECT 'ჩასაშენებელი ქურის ზედაპირი' UNION ALL SELECT 'ჰობი' UNION ALL SELECT 'hob' UNION ALL SELECT 'варочная панель' UNION ALL SELECT 'ქურის ზედაპირი') w WHERE @sid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonym_words x WHERE x.synonym_id = @sid AND x.word = w.word);
INSERT INTO cscart_csc_live_search_synonyms (company_id, phrase, synonyms, `timestamp`, user_id, lang_code, status) SELECT 1, 'გაზის ქურის ზედაპირი', '["ჩასაშენებელი გაზქურა","გაზქურის ზედაპირი","გაზის ზედაპირი","გაზის ჩასაშენებელი ზედაპირი"]', UNIX_TIMESTAMP(), 0, 'ka', 'A' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'გაზის ქურის ზედაპირი');
INSERT INTO cscart_csc_live_search_synonym_words (synonym_id, company_id, lang_code, word, is_variant) SELECT @sid, 1, 'ka', w.word, 0 FROM (SELECT 'ჩასაშენებელი გაზქურა' AS word UNION ALL SELECT 'გაზქურის ზედაპირი' UNION ALL SELECT 'გაზის ზედაპირი' UNION ALL SELECT 'გაზის ჩასაშენებელი ზედაპირი' UNION ALL SELECT 'გაზის ქურის ზედაპირი') w WHERE @sid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonym_words x WHERE x.synonym_id = @sid AND x.word = w.word);
INSERT INTO cscart_csc_live_search_synonyms (company_id, phrase, synonyms, `timestamp`, user_id, lang_code, status) SELECT 1, 'ინდუქციური ქურის ზედაპირი', '["ინდუქციური ქურა","ინდუქციური ზედაპირი","ინდუქცია","индукционная плита","индукционная панель"]', UNIX_TIMESTAMP(), 0, 'ka', 'A' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'ინდუქციური ქურის ზედაპირი');
INSERT INTO cscart_csc_live_search_synonym_words (synonym_id, company_id, lang_code, word, is_variant) SELECT @sid, 1, 'ka', w.word, 0 FROM (SELECT 'ინდუქციური ქურა' AS word UNION ALL SELECT 'ინდუქციური ზედაპირი' UNION ALL SELECT 'ინდუქცია' UNION ALL SELECT 'индукционная плита' UNION ALL SELECT 'индукционная панель' UNION ALL SELECT 'ინდუქციური ქურის ზედაპირი') w WHERE @sid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonym_words x WHERE x.synonym_id = @sid AND x.word = w.word);
INSERT INTO cscart_csc_live_search_synonyms (company_id, phrase, synonyms, `timestamp`, user_id, lang_code, status) SELECT 1, 'ელექტრო ქურის ზედაპირი', '["კერამიკული ქურა","მინაკერამიკული ქურა","ვიტროკერამიკული ქურა","ელექტრო ზედაპირი"]', UNIX_TIMESTAMP(), 0, 'ka', 'A' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonyms WHERE company_id = 1 AND lang_code = 'ka' AND phrase = 'ელექტრო ქურის ზედაპირი');
INSERT INTO cscart_csc_live_search_synonym_words (synonym_id, company_id, lang_code, word, is_variant) SELECT @sid, 1, 'ka', w.word, 0 FROM (SELECT 'კერამიკული ქურა' AS word UNION ALL SELECT 'მინაკერამიკული ქურა' UNION ALL SELECT 'ვიტროკერამიკული ქურა' UNION ALL SELECT 'ელექტრო ზედაპირი' UNION ALL SELECT 'ელექტრო ქურის ზედაპირი') w WHERE @sid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cscart_csc_live_search_synonym_words x WHERE x.synonym_id = @sid AND x.word = w.word);
